import{_ as a,o as i,c as o,a0 as l}from"./chunks/framework.BL79I5mR.js";const h=JSON.parse('{"title":"Hidráulica 1D","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/hidraulica/index.md","filePath":"es/explanation/hidraulica/index.md"}'),n={name:"es/explanation/hidraulica/index.md"};function d(r,e,t,s,c,m){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="hidraulica-1d" tabindex="-1">Hidráulica 1D <a class="header-anchor" href="#hidraulica-1d" aria-label="Permalink to &quot;Hidráulica 1D&quot;">​</a></h1><p>La descripción a nivel de ecuaciones del proceso de cálculo hidráulico 1D del motor de LocalSWMM, transcrita desde el código fuente del motor. Léelos en orden; los artículos posteriores se construyen sobre los anteriores.</p><ol><li><a href="./01-modelo-conceptual.html">Modelo conceptual</a> — alcance, modelo conceptual de nodos y enlaces, variables de estado, las cuatro formulaciones de tránsito.</li><li><a href="./02-componentes-del-modelo.html">Componentes del modelo</a> — datos de nodos, datos de enlaces, pendiente y longitud, alargamiento de conductos.</li><li><a href="./03-orquestacion-de-la-simulacion.html">Orquestación de la simulación</a> — el ciclo de avance temporal, relojes de escorrentía y tránsito, aportes laterales.</li><li><a href="./04-geometria-de-secciones.html">Geometría de secciones</a> — las cuatro relaciones geométricas, Manning y el factor de sección.</li><li><a href="./05-formulaciones-de-transito.html">Formulaciones de tránsito</a> — flujo permanente y onda cinemática.</li><li><a href="./06-solver-de-onda-dinamica.html">Solver de onda dinámica</a> — ecuaciones de St. Venant, diferencias finitas, la iteración de Picard.</li><li><a href="./07-kernel-de-momentum-de-enlaces.html">Kernel de momentum de enlaces</a> — velocidad, número de Froude, los seis términos de momentum, limitación de flujo.</li><li><a href="./08-continuidad-de-nodo.html">Continuidad de nodo</a> — actualizaciones explícita y semi-implícita, inundación y encharcamiento.</li><li><a href="./09-metodos-de-sobrenivel.html">Métodos de sobrenivel</a> — EXTRAN y ranura de Preissmann estática/dinámica.</li><li><a href="./10-estructuras-y-condiciones-de-borde.html">Estructuras y condiciones de borde</a> — bombas, orificios, vertederos, descargas, emisarios, divisores.</li><li><a href="./11-estabilidad-y-paso-de-tiempo.html">Estabilidad y paso de tiempo</a> — condición de Courant, balance de masa.</li><li><a href="./12-opciones-y-valores-por-defecto.html">Opciones y valores por defecto</a> — la superficie de configuración del motor.</li></ol><p>La fuente LaTeX original es <a href="./../../../sources/1d_hidraulica.tex.html">1d_hidraulica.tex</a>. El espejo en inglés está en <a href="/docs/explanation/hydraulics/">1D Hydraulics</a>.</p>',4)])])}const p=a(n,[["render",d]]);export{h as __pageData,p as default};
